  position?: Vector3;
  rotation?: Quaternion;
  duration?: number;
  easingFunction?: (t: number) => number;
}

interface AnimationCallback {
  (progress: number): void;
}

class ThreeDCameraAnimation {
  private _camera: any; // Replace 'any' with the actual camera class
  private _target: Transform;

