    this._camera = camera;
    this._target = target;
  }

  public animateTo(options: CameraOptions, callback: AnimationCallback) {
    const { position = {}, rotation = {}, duration = 1000, easingFunction = (t) => t } = options;

    const startPosition = this._camera.position.clone();
    const startRotation = new Quaternion().copy(this._camera.rotation);
    const targetPosition = position.position || startPosition;
    const targetRotation = rotation.rotation || new Quaternion();

