import 'dart:collection';

class Transaction {
  final String coinName;
  final DateTime dateTime;
  final double profitLoss;

  Transaction(this.coinName, this.dateTime, this.profitLoss);
}

List<Map<String, dynamic>> topCoins({required List<Transaction> transactions}) {
  Map<String, List<double>> coinProfits = {};
  Map<String, List<double>> coinLosses = {};

  for (var transaction in transactions) {
    if (!coinProfits.containsKey(transaction.coinName)) {
      coinProfits[transaction.coinName] = [0.0];
    }
    coinProfits[transaction.coinName]!.add(transaction.profitLoss);

    if (!coinLosses.containsKey(transaction.coinName)) {
      coinLosses[transaction.coinName] = [0.0];
    }
    coinLosses[transaction.coinName]!.add(-transaction.profitLoss);
  }

  var sortedProfitCoins = coinProfits.entries.map((e) => MapEntry(e.key, e.value.reduce((a, b) => a + b) / transactions.length));
  var sortedLossCoins = coinLosses.entries.map((e) => MapEntry(e.key, e.value.reduce((a, b) => a + b) / transactions.length));

  return [
