function sortJsonByKeys(jsonObj) {
  // First, convert the JSON object into an array of key-value pairs using Object.entries()
  const entries = Object.entries(jsonObj);

  // Next, use Array.prototype.sort() to sort the entries array based on the keys
  entries.sort((a, b) => {
    // Use localeCompare() to ensure that strings are sorted case-insensitively
    return a[0].localeCompare(b[0], undefined, { sensitivity: 'accent' });
  });

  // Finally, create a new JSON object from the sorted entries array
  const sortedJsonObj = Object.fromEntries(entries);

  return sortedJsonObj;
}

